// A dependency whose first load of node:punycode is a dynamic import.
"use strict";

module.exports = async function toAscii(domain) {
  // The awaited namespace binds first, so this file's import is the
  // module's first load whichever way the caller uses the result.
  const punycode = await import("punycode");
  return punycode.default.toASCII(domain);
};
